INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fox', 'n.', '/fɒks/', '狐狸', 'In London, a clever fox can find food in the bins at night.', '在伦敦,聪明的狐狸夜里能在垃圾箱里找到食物。', 'Survival', 1, 0, 'senior', 'wordlist', 'elective2', 'U6', 'an urban fox', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crime', 'n.', '/kraɪm/', '罪;罪行', 'Stealing food from an open car was the baboon''s daily crime.', '从敞开的车里偷食物是这只狒狒每天的“罪行”。', 'Survival', 2, 0, 'senior', 'wordlist', 'elective2', 'U6', 'commit a crime', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suburb', 'n.', '/ˈsʌbɜːb/', '郊区;城郊', 'The theft took place in a quiet seaside suburb of the city.', '偷窃发生在城市一个安静的海滨郊区。', 'Survival', 3, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a seaside suburb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'greedy', 'adj.', '/ˈɡriːdi/', '贪婪的,贪心的', 'The greedy thief grabbed the bag of shopping and ran away.', '贪婪的小偷抓起那袋购物品就跑了。', 'Survival', 4, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a greedy thief', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'thief', 'n.', '/θiːf/', '小偷,贼', 'The real thief turned out to be a wild baboon, not a person.', '真正的“小偷”原来是一只野生狒狒,而不是人。', 'Survival', 5, 0, 'senior', 'wordlist', 'elective2', 'U6', 'catch a thief', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'commit', 'v.', '/kəˈmɪt/', '犯(错误或罪行)', 'No matter how many crimes the animal would commit, no one could arrest it.', '无论这只动物犯下多少“罪行”,都没人能逮捕它。', 'Survival', 6, 0, 'senior', 'wordlist', 'elective2', 'U6', 'commit a crime', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'urban', 'adj.', '/ˈɜːbən/', '城镇的,城市的', 'Foxes, lions and wild pigs are becoming common urban animals.', '狐狸、狮子和野猪正成为常见的城市动物。', 'Survival', 7, 0, 'senior', 'wordlist', 'elective2', 'U6', 'urban animals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'predator', 'n.', '/ˈpredətə/', '掠食动物,捕食性动物', 'Out of reach of their natural predators, the newcomers often do well.', '由于远离天敌,这些新来者往往生存得很好。', 'Survival', 8, 0, 'senior', 'wordlist', 'elective2', 'U6', 'natural predators', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'newcomer', 'n.', '/ˈnjuːkʌmə/', '新来者', 'For its wildest newcomers, a green city can offer many benefits.', '对于最野的新来者,一座绿色的城市能提供许多好处。', 'Survival', 9, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a wild newcomer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'flourish', 'v.', '/ˈflʌrɪʃ/', '生长茂盛;兴盛', 'Far from danger, these animals flourish in their new city lives.', '远离危险,这些动物在新的城市生活中兴旺起来。', 'Survival', 10, 0, 'senior', 'wordlist', 'elective2', 'U6', 'flourish in cities', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'container', 'n.', '/kənˈteɪnə/', '容器', 'Clever racoons learn how to open bins and other containers for food.', '聪明的浣熊学会了打开垃圾桶和其他容器找吃的。', 'Survival', 11, 0, 'senior', 'wordlist', 'elective2', 'U6', 'open a container', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'garbage', 'n.', '/ˈɡɑːbɪdʒ/', '垃圾', 'Hungry animals find plenty to eat in the garbage we throw away.', '饥饿的动物能在我们丢弃的垃圾里找到很多吃的。', 'Survival', 12, 0, 'senior', 'wordlist', 'elective2', 'U6', 'in the garbage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'lamb', 'n.', '/læm/', '羔羊肉', 'Urban foxes have even got a taste for lamb kebabs from the bins.', '城市里的狐狸甚至爱上了垃圾箱里的羊肉串。', 'Survival', 13, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a lamb kebab', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'garlic', 'n.', '/ˈɡɑːlɪk/', '(大)蒜', 'Some city foxes will eat anything, even leftover garlic bread.', '有些城市狐狸什么都吃,连剩下的蒜香面包也吃。', 'Survival', 14, 0, 'senior', 'wordlist', 'elective2', 'U6', 'garlic bread', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'estimate', 'v.', '/ˈestɪmeɪt/', '估计,估算', 'Scientists estimate that up to a billion birds die from window crashes each year.', '科学家估计每年多达十亿只鸟死于撞窗。', 'Survival', 15, 0, 'senior', 'wordlist', 'elective2', 'U6', 'scientists estimate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'migratory', 'adj.', '/maɪˈɡreɪtəri/', '迁徙的', 'Some birds have not yet changed their old migratory routes through the city.', '有些鸟还没有改变它们穿过城市的古老迁徙路线。', 'Survival', 16, 0, 'senior', 'wordlist', 'elective2', 'U6', 'migratory routes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'appreciate', 'v.', '/əˈpriːʃieɪt/', '欣赏;赏识;感激', 'We should learn to understand and appreciate our wild neighbours.', '我们应当学会理解并欣赏我们的野生邻居。', 'Survival', 17, 0, 'senior', 'wordlist', 'elective2', 'U6', 'appreciate nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'crucial', 'adj.', '/ˈkruːʃ(ə)l/', '至关重要的,关键性的', 'The ability to adapt is crucial to the survival of urban animals.', '适应能力对城市动物的生存至关重要。', 'Survival', 18, 0, 'senior', 'wordlist', 'elective2', 'U6', 'crucial to survival', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'restrict', 'v.', '/rɪˈstrɪkt/', '限制,控制', 'Some people argue that we should restrict building to protect wild habitats.', '有人认为我们应限制建设以保护野生栖息地。', 'Survival', 19, 0, 'senior', 'wordlist', 'elective2', 'U6', 'restrict development', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'hiker', 'n.', '/ˈhaɪkə/', '徒步旅行者,远足者', 'Whether you are a first-time hiker or an old camper, read the safety tips.', '无论你是初次远足者还是老露营者,都要读读安全提示。', 'Survival', 20, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a first-time hiker', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'kit', 'n.', '/kɪt/', '成套工具', 'Wherever you go in the wild, always take a first-aid kit with you.', '在野外无论去哪里,都要随身带上急救包。', 'Survival', 21, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a first-aid kit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'optimistic', 'adj.', '/ˌɒptɪˈmɪstɪk/', '乐观的', 'A clever and optimistic person has a better chance of surviving a crisis.', '一个聪明而乐观的人在危机中有更大的生存机会。', 'Survival', 22, 0, 'senior', 'wordlist', 'elective2', 'U6', 'stay optimistic', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'clay', 'n.', '/kleɪ/', '黏土', 'Robinson Crusoe made his own cups out of clay on the island.', '鲁滨逊在岛上用黏土做了自己的杯子。', 'Survival', 23, 0, 'senior', 'wordlist', 'elective2', 'U6', 'out of clay', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cave', 'n.', '/keɪv/', '洞穴', 'He spent days digging a cave to keep himself safe at night.', '他花了好几天挖了一个洞穴,以便夜里保护自己。', 'Survival', 24, 0, 'senior', 'wordlist', 'elective2', 'U6', 'dig a cave', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fuel', 'n.', '/ˈfjuːəl/', '燃料', 'The government has announced measures to limit the use of fuel.', '政府已宣布措施来限制燃料的使用。', 'Survival', 25, 0, 'senior', 'wordlist', 'elective2', 'U6', 'limit fuel use', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'consumption', 'n.', '/kənˈsʌmpʃ(ə)n/', '(能源、油、电等的)消耗量', 'Emergency rules were made to cut the country''s fuel consumption.', '为削减该国的燃料消耗,出台了紧急规定。', 'Survival', 26, 0, 'senior', 'wordlist', 'elective2', 'U6', 'fuel consumption', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'supplement', 'v.', '/ˈsʌplɪment/', '补充,增补', 'Scientists are looking for new energy sources to supplement oil supplies.', '科学家正在寻找新能源来补充石油供应。', 'Survival', 27, 0, 'senior', 'wordlist', 'elective2', 'U6', 'supplement supplies', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'eliminate', 'v.', '/ɪˈlɪmɪneɪt/', '消除,根除', 'A three-year programme aims to eliminate the rats introduced to the island.', '一项三年计划旨在根除被引入岛上的老鼠。', 'Survival', 28, 0, 'senior', 'wordlist', 'elective2', 'U6', 'eliminate a danger', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'firefighter', 'n.', '/ˈfaɪəfaɪtə/', '消防队员', 'After hours of hard work, the firefighters brought the blaze under control.', '经过数小时的艰苦努力,消防员控制住了大火。', 'Survival', 29, 0, 'senior', 'wordlist', 'elective2', 'U6', 'local firefighters', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'blaze', 'n.', '/bleɪz/', '烈火,大火', 'Local firefighters stopped the huge blaze from spreading any further.', '当地消防员阻止了这场大火进一步蔓延。', 'Survival', 30, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a huge blaze', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fierce', 'adj.', '/fɪəs/', '恶劣的,极端的;凶猛的', 'They battled the fire for hours in fierce and dangerous conditions.', '他们在恶劣而危险的条件下与火搏斗了数小时。', 'Survival', 31, 0, 'senior', 'wordlist', 'elective2', 'U6', 'fierce conditions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'react', 'v.', '/riˈækt/', '(作出)反应', 'We talked about how people react when a sudden crisis breaks out.', '我们谈到当突发危机时人们如何反应。', 'Survival', 32, 0, 'senior', 'wordlist', 'elective2', 'U6', 'react to a crisis', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'monthly', 'adj.', '/ˈmʌnθli/', '每月一次的', 'Survivor is a new monthly magazine about disaster and survival.', '《幸存者》是一本关于灾难与生存的新月刊。', 'Survival', 33, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a monthly magazine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nuclear', 'adj.', '/ˈnjuːkliə/', '核(武器)的', 'In the past, the greatest fear was that nuclear missiles could wipe out life.', '过去人们最大的恐惧是核导弹会消灭一切生命。', 'Survival', 34, 0, 'senior', 'wordlist', 'elective2', 'U6', 'nuclear missiles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advanced', 'adj.', '/ədˈvɑːnst/', '高级的;先进的', 'Nuclear weapons could destroy humans and other advanced life forms.', '核武器可能毁灭人类和其他高级生命形式。', 'Survival', 35, 0, 'senior', 'wordlist', 'elective2', 'U6', 'advanced life forms', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wipe', 'v.', '/waɪp/', '擦,拭;(wipe out)彻底消灭', 'A single disaster could wipe out the whole human race in a moment.', '一场灾难可能在顷刻间消灭整个人类。', 'Survival', 36, 0, 'senior', 'wordlist', 'elective2', 'U6', 'wipe out life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'orbit', 'v.', '/ˈɔːbɪt/', '环绕……运行', 'Our probes orbit Mars and send back valuable data and images.', '我们的探测器环绕火星运行,传回宝贵的数据和图像。', 'Survival', 37, 0, 'senior', 'wordlist', 'elective2', 'U6', 'orbit the planet', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'agency', 'n.', '/ˈeɪdʒ(ə)nsi/', '机构;局,部,处', 'Space agencies of several countries are planning manned missions to Mars.', '几个国家的航天机构正在计划载人火星任务。', 'Survival', 38, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a space agency', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'consist', 'v.', '/kənˈsɪst/', '组成,构成', 'Biosphere 2 consisted of a closed space where people and plants lived together.', '“生物圈二号”由一个人和植物共同生活的封闭空间组成。', 'Survival', 39, 0, 'senior', 'wordlist', 'elective2', 'U6', 'consist of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'infer', 'v.', '/ɪnˈfɜː/', '推断,推定', 'From the long journey, we can infer that reaching Mars is very risky.', '从漫长的旅程我们可以推断,抵达火星非常危险。', 'Survival', 40, 0, 'senior', 'wordlist', 'elective2', 'U6', 'infer from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'expose', 'v.', '/ɪkˈspəʊz/', '使暴露(于险境)', 'Travelling to Mars would expose the crew to dangerous solar radiation.', '前往火星会使机组人员暴露在危险的太阳辐射中。', 'Survival', 41, 0, 'senior', 'wordlist', 'elective2', 'U6', 'expose to radiation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'exposure', 'n.', '/ɪkˈspəʊʒə/', '暴露', 'The spacesuit protects the astronaut from exposure to the Martian surface.', '宇航服保护宇航员免于暴露在火星表面。', 'Survival', 42, 0, 'senior', 'wordlist', 'elective2', 'U6', 'exposure to the surface', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'astronaut', 'n.', '/ˈæstrənɔːt/', '宇航员,太空人', 'The lonely astronaut was left behind after a dust storm on Mars.', '一场沙尘暴后,这名孤独的宇航员被留在了火星上。', 'Survival', 43, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a lonely astronaut', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dust', 'n.', '/dʌst/', '沙土,尘土', 'He lost contact with the others when he was caught in a dust storm.', '他被困在一场沙尘暴中,与其他人失去了联系。', 'Survival', 44, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a dust storm', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'capsule', 'n.', '/ˈkæpsjuːl/', '(航天器的)密封舱,太空舱', 'The landing capsule protects him from the deadly radiation outside.', '着陆舱保护他免受外面致命的辐射。', 'Survival', 45, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a landing capsule', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'trunk', 'n.', '/trʌŋk/', '树干', 'The green lizards lived on the lower branches and trunks of the trees.', '绿蜥蜴生活在树木较低的枝条和树干上。', 'Survival', 46, 0, 'senior', 'wordlist', 'elective2', 'U6', 'the trunk of a tree', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'indoors', 'adv.', '/ˌɪnˈdɔːz/', '在室内', 'During the heat wave, people were advised to stay indoors and rest.', '热浪期间,人们被建议待在室内休息。', 'Survival', 47, 0, 'senior', 'wordlist', 'elective2', 'U6', 'stay indoors', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'hostile', 'adj.', '/ˈhɒstaɪl/', '(环境)恶劣的;有敌意的', 'Mars has a less hostile environment than the other planets.', '与其他行星相比,火星的环境没那么恶劣。', 'Survival', 48, 0, 'senior', 'wordlist', 'elective2', 'U6', 'a hostile environment', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u6.01', '①whatever / whoever / whichever(= no matter what/who/which,作让步状语)', 'A2', 11, '外研社版选择性必修第二册 U6 — whatever(= no matter what)、whoever(= no matter who)、whichever(= no matter which)在让步状语从句里充当从句的主语、宾语或限定词;though/although 不能充当这些成分,故不可用。', 1, 'elective2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u6.02', '②wherever / whenever / however(+ adj./adv.,= no matter where/when/how)', 'A2', 11, '外研社版选择性必修第二册 U6 — wherever(= no matter where)指地点、whenever(= no matter when)指时间;however 后接形容词或副词,意为 no matter how(不论多么……),不同于表示“但是”的 however。', 2, 'elective2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u6.03', '③-ever 让步状语 vs 名词性从句用法 · 与 no matter 互换', 'A2', 11, '外研社版选择性必修第二册 U6 — whatever/whoever 既能引导让步状语从句(= no matter what/who),也能引导名词性从句作主语/宾语;两种情况 though/although 都不可用。no matter + what/who/where/when/how = 相应的 -ever 词。', 3, 'elective2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ happens in the wild, a calm mind is your best tool for survival."', 'Whatever', 'Whoever', 'Wherever', 'Although', 'A', '空作 happens 的主语、表“不论什么事”→ whatever(= no matter what);although 不能作主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ you find in the cave, do not eat it unless you are sure it is safe."', 'Whoever', 'Whatever', 'However', 'Although', 'B', '空作 find 的宾语、指物 → whatever;although 不能作宾语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ leads the team into the jungle must carry a map and a kit."', 'Whatever', 'Wherever', 'Whoever', 'Although', 'C', '空作 leads 的主语、指人 → whoever(= no matter who)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ reaches the survivor first should keep him warm until help comes."', 'Whichever', 'Whatever', 'Although', 'Whoever', 'D', '空作主语、指人 → whoever;although 不能作主语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ path you choose down the mountain, watch out for loose rocks."', 'Whichever', 'Whoever', 'Whenever', 'Although', 'A', '空限定 path、表“从若干条路里不论哪条”→ whichever(= no matter which)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ tools you take to Mars, water and oxygen still matter most."', 'Whoever', 'Whatever', 'Wherever', 'Though', 'B', '空限定 tools、指物 → whatever;though 不能作限定词。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ finds the underground ice first will solve the water problem."', 'Whatever', 'Whichever', 'Whoever', 'Although', 'C', '空作主语、指人 → whoever。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ the storm destroys, the astronauts must rebuild it quickly."', 'Whoever', 'Wherever', 'Although', 'Whatever', 'D', '空作 destroys 的宾语、指物 → whatever。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ shelter you build, make sure it blocks the deadly radiation."', 'Whatever', 'Whoever', 'Wherever', 'Although', 'A', '空限定 shelter、指物 → whatever;although 不能加名词。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ of the two routes you take, tell someone where you are going."', 'Whoever', 'Whichever', 'Whenever', 'Although', 'B', '“of the two”表二者择一 → whichever(= no matter which)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ you trust in a crisis, choose someone who stays calm."', 'Whatever', 'Wherever', 'Whoever', 'Though', 'C', '空作 trust 的宾语、指人 → whoever。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ the doctors test, they hope to find a cure for the new disease."', 'Whoever', 'Whenever', 'Although', 'Whatever', 'D', '空作 test 的宾语、指物 → whatever。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ wants to survive on the island must learn to be patient."', 'Whoever', 'Whatever', 'Whichever', 'Although', 'A', '空作 wants 的主语、指人 → whoever。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ the firefighters do next, they must not let the blaze spread."', 'Whoever', 'Whatever', 'Wherever', 'Although', 'B', '空作 do 的宾语、指物/事 → whatever。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ medicine the scientists try, the struggle against the virus goes on."', 'Whoever', 'Whenever', 'Whatever', 'Although', 'C', '空限定 medicine、指物 → whatever。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ of you has the first-aid kit should treat the wound right away."', 'Whatever', 'Wherever', 'Although', 'Whichever', 'D', '“of you”表从你们之中择一 → whichever。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ the rising sea takes from the island, the people will not give up."', 'Whatever', 'Whoever', 'Whenever', 'Though', 'A', '空作 takes 的宾语、指物 → whatever。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ joins the rescue mission needs courage and a clear head."', 'Whatever', 'Whoever', 'Whichever', 'Although', 'B', '空作 joins 的主语、指人 → whoever。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ animal moves into the city, it is only trying to survive."', 'Whoever', 'Wherever', 'Whatever', 'Although', 'C', '空限定 animal、指物 → whatever。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.01'), '"____ you decide to do, never panic when a wildfire breaks out."', 'Whoever', 'Wherever', 'Although', 'Whatever', 'D', '空作 do 的宾语、指物/事 → whatever。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ they go, urban animals find towns and cities in their way."', 'Wherever', 'Whenever', 'However', 'Although', 'A', '表“不论去到哪里”、地点 → wherever(= no matter where)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ hard the two-year treatment was, Jane never gave up hope."', 'Whenever', 'However', 'Wherever', 'Although', 'B', '空后接形容词 hard、意为 no matter how → however;although 不直接加形容词。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ a wildfire breaks out, leave the area quickly but calmly."', 'Wherever', 'However', 'Whenever', 'Although', 'C', '表“每当、不论何时”、时间 → whenever(= no matter when)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ you go in the wild, take a first-aid kit with you."', 'Whenever', 'However', 'Though', 'Wherever', 'D', '表“去野外的任何地方”、地点 → wherever。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ fast the birds fly, some still crash into the glass towers."', 'However', 'Whenever', 'Wherever', 'Although', 'A', '空后接副词 fast、意为 no matter how → however。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the temperature rises above forty degrees, people are warned to stay indoors."', 'Wherever', 'Whenever', 'However', 'Although', 'B', '表“每当气温升到……时”、时间 → whenever。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ foxes settle in the city, they soon learn to find food."', 'Whenever', 'However', 'Wherever', 'Although', 'C', '表“在城里安家的任何地方”、地点 → wherever。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ dangerous the journey to Mars may be, scientists still dream of it."', 'Whenever', 'Wherever', 'Though', 'However', 'D', '空后接形容词 dangerous、意为 no matter how → however。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the rescue team arrives, the survivor must keep himself warm until then."', 'Whenever', 'Wherever', 'However', 'Although', 'A', '表“不论何时到达”、时间 → whenever。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ humans build their cities, wild animals try to live alongside them."', 'Whenever', 'Wherever', 'However', 'Although', 'B', '表“在人类建城的任何地方”、地点 → wherever。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ carefully you plan, survival in the wild can still be hard."', 'Whenever', 'Wherever', 'However', 'Although', 'C', '空后接副词 carefully、意为 no matter how → however。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the heat wave returns, swimming pools fill with people cooling down."', 'Wherever', 'However', 'Though', 'Whenever', 'D', '表“每当热浪重来时”、时间 → whenever。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the astronaut looks on Mars, he sees only red, empty land."', 'Wherever', 'Whenever', 'However', 'Although', 'A', '表“朝任何地方看”、地点 → wherever。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ tired she felt, Jane kept inviting people to donate tissue samples."', 'Whenever', 'However', 'Wherever', 'Although', 'B', '空后接形容词 tired、意为 no matter how → however。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ a crisis appears, calm people look for a solution instead of panicking."', 'Wherever', 'However', 'Whenever', 'Although', 'C', '表“每当危机出现时”、时间 → whenever。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ you camp for the night, choose a spot far from wild animals."', 'Whenever', 'However', 'Although', 'Wherever', 'D', '表“在你过夜的任何地方”、地点 → wherever。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ deep the snow became, the climbers pushed on towards the shelter."', 'However', 'Whenever', 'Wherever', 'Though', 'A', '空后接形容词 deep、意为 no matter how → however。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the river floods, the village quickly moves to higher ground."', 'Wherever', 'Whenever', 'However', 'Although', 'B', '表“每当河水泛滥时”、时间 → whenever。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ the survivor travels on the island, he marks the path behind him."', 'Whenever', 'However', 'Wherever', 'Although', 'C', '表“在岛上去到的任何地方”、地点 → wherever。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.02'), '"____ slowly the rescue comes, hope keeps the lost hiker going."', 'Whenever', 'Wherever', 'Although', 'However', 'D', '空后接副词 slowly、意为 no matter how → however。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"You may take ____ you need from the emergency box before you leave."', 'whatever', 'whoever', 'wherever', 'although', 'A', '引导名词性从句作 take 的宾语、指物 → whatever;although 不能引导名词性从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ reaches the lifeboat first should help the weaker passengers aboard."', 'Whatever', 'Whoever', 'However', 'Although', 'B', '引导名词性从句作主语、指人 → whoever。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ the reasons behind the animals entering our cities, survival comes first."', 'Whoever', 'Wherever', 'Whatever', 'Although', 'C', '让步状语(= no matter what)、后接名词 the reasons → whatever;although 不能直接加名词。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Robinson Crusoe made good use of ____ he could save from the wrecked ship."', 'whoever', 'whenever', 'although', 'whatever', 'D', '引导名词性从句作介词 of 的宾语、指物 → whatever。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"No matter ____ happens, a calm survivor keeps looking for a way out."', 'what', 'who', 'where', 'although', 'A', 'no matter what = whatever、空作 happens 的主语、指物 → what。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"The rescue team will help ____ is still trapped under the fallen rocks."', 'whatever', 'whoever', 'wherever', 'although', 'B', '引导名词性从句作 help 的宾语、指人 → whoever。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"No matter ____ hard the climb is, the team refuses to turn back."', 'what', 'where', 'how', 'although', 'C', 'no matter how + 形容词 hard = however hard → how。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Share the clean water with ____ needs it most in the group."', 'whatever', 'whenever', 'although', 'whoever', 'D', '引导名词性从句作介词 with 的宾语、指人作 needs 的主语 → whoever。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ the storm leaves behind, the islanders will rebuild their homes."', 'Whatever', 'Whoever', 'However', 'Although', 'A', '让步状语、空作 leaves 的宾语、指物 → whatever。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"No matter ____ you go on the island, hunger will find you in the end."', 'what', 'where', 'who', 'although', 'B', 'no matter where = wherever、表地点 → where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"The doctors will test ____ medicine might cure the new disease."', 'whoever', 'wherever', 'whatever', 'although', 'C', '引导名词性从句、限定 medicine 作 test 的宾语 → whatever。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ you meet in the wild, treat them with respect and caution."', 'Whatever', 'Wherever', 'Although', 'Whoever', 'D', '让步状语、空作 meet 的宾语、指人 → whoever。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"No matter ____ leads the team, the group must stay together."', 'who', 'what', 'where', 'although', 'A', 'no matter who = whoever、指人作 leads 的主语 → who。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Eat ____ the land can safely give you, and waste nothing."', 'whoever', 'whatever', 'whenever', 'although', 'B', '引导名词性从句作 eat 的宾语、指物 → whatever。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ the future may hold, Jane is determined to live a full life."', 'Whoever', 'However', 'Whatever', 'Although', 'C', '让步状语(= no matter what)、空作 hold 的宾语 → whatever。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Give the warm blanket to ____ feels the cold the most."', 'whatever', 'wherever', 'although', 'whoever', 'D', '引导名词性从句作介词 to 的宾语、指人作 feels 的主语 → whoever。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"No matter ____ the rescue arrives, we must keep the fire burning as a signal."', 'when', 'what', 'who', 'although', 'A', 'no matter when = whenever、表时间 → when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Tell ____ you can reach that the path down the mountain is blocked."', 'whatever', 'whoever', 'whenever', 'although', 'B', '引导名词性从句作 tell 的间接宾语、指人 → whoever。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"____ difficulties she might face, Jane keeps helping other patients recover."', 'Whoever', 'However', 'Whatever', 'Although', 'C', '让步状语、限定 difficulties → whatever;although 不能直接加名词。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U6' AND code='fe2u6.03'), '"Use ____ tools you have to dig the cave deeper before night falls."', 'whoever', 'however', 'although', 'whatever', 'D', '引导名词性从句、限定 tools 作 use 的宾语 → whatever。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Animals Move Into Town', 'In a seaside suburb of Cape Town, a greedy thief once reached into a car and ran off with a bag of shopping. Yet this was no ordinary criminal — it was a wild baboon. No matter how many times it stole, the police were powerless to stop it. Scenes like this, once almost unheard of, are now common in cities around the world. Foxes trot through London, mountain lions appear in San Francisco, and wild pigs wander the streets of Hong Kong. It is almost as if our towns are being taken over by wild creatures. Many people believe that the growth of cities and the change of climate have pushed these animals out of their natural homes. The truth, however, is more surprising. Some of these so-called urban animals have never moved at all. Instead, it is we humans who have spread into their land. Wherever they turn, the animals find streets and buildings in their way, and they have little choice but to live beside us.', '说明·城市里的野生动物', 169, '[{"q":"Who turned out to be the ''thief'' in the seaside suburb?","answer":"A","options":["A wild baboon searching for food.","A clever local criminal.","A hungry fox from London.","A careless police officer."],"explanation":"原文说那个“窃贼”其实是 a wild baboon 的转述。"},{"q":"What surprising point does the writer make about urban animals?","answer":"B","options":["They were all brought into cities by people.","Many never moved, while humans spread into their land.","They prefer cities to any natural home.","They are far less common than before."],"explanation":"对 ''it is we humans who have spread into their land'' 的概括转述。"},{"q":"According to the passage, why do the animals live beside us?","answer":"A","options":["Human towns now block the places they once roamed.","They enjoy the noise of city life.","Cities are always safer than the wild.","People feed them every day on purpose."],"explanation":"对 ''the animals find streets and buildings in their way'' 的转述。"}]'::jsonb, '[{"word":"baboon","cn":"狒狒"},{"word":"suburb","cn":"郊区"},{"word":"urban","cn":"城市的"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Why Cities Suit Wild Animals', 'As our cities grow greener, they offer more and more welcoming spaces to animals in search of a new home. Far from the natural hunters that once chased them, these newcomers often flourish in their city lives. Foxes, for example, can now be seen all over London. One was even found living high up inside a tall building while it was still being built. There is more good news for hungry animals, too. They find plenty to eat in our gardens and in the food we throw away each day. Some have learned to enjoy the many kinds of meals our cities offer, from leftover bread to pieces of meat. The city is far from a perfect home, yet for its wildest new arrivals it brings real benefits: safety, shelter and an easy supply of food. This is one reason why the number of these animals keeps rising. As long as a city can meet their simple needs, the wild creatures will keep moving in and staying on.', '说明·城市为何吸引动物', 168, '[{"q":"Why do many animals do well in cities, according to the text?","answer":"B","options":["They are kept safely in zoos.","They no longer live near the predators that used to hunt them.","They are trained by city people.","They sleep through the whole winter."],"explanation":"对 ''Far from the natural hunters that once chased them… flourish'' 的转述。"},{"q":"What does the example of the fox in the tall building show?","answer":"C","options":["Foxes can settle in surprising city places.","Foxes only live in gardens.","Foxes dislike living in London.","Foxes refuse human food."],"explanation":"用伦敦高楼里的狐狸说明城市动物能在意想不到的地方安家;其余与文意相反。"},{"q":"What benefits does the city bring its wildest new arrivals?","answer":"D","options":["Higher prices and more rules.","Colder weather and less light.","Fewer places to hide.","Safety, shelter and easy food."],"explanation":"对 ''safety, shelter and an easy supply of food'' 的转述。"}]'::jsonb, '[{"word":"flourish","cn":"兴盛"},{"word":"newcomer","cn":"新来者"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'When Birds Meet Glass', 'Not every animal does well in the city. For some, the modern world hides a deadly trap. Many birds simply cannot tell the difference between the open blue sky and a sheet of clear glass. Because of this, they fly straight into windows at speeds of about fifty kilometres an hour. Scientists estimate that somewhere between four hundred million and one billion birds die from these crashes every year in the United States alone. Shockingly, that may be around one in every ten birds in the country. Some kinds of birds suffer far more than others. One idea is that these birds have not yet changed the old travelling routes that lead them, year after year, through cities full of high towers. For these unlucky travellers, the bright modern city is not a home at all, but a hidden danger in their path. Until our buildings change, the safest skies for them may still lie far away from town.', '说明·鸟撞玻璃的危险', 159, '[{"q":"Why do many birds fly into city windows?","answer":"A","options":["They cannot tell clear glass from the open sky.","They are chasing insects on the glass.","They are trying to enter the buildings.","They like the warmth of the towers."],"explanation":"对 ''cannot tell the difference between the open blue sky and a sheet of clear glass'' 的转述。"},{"q":"What do the numbers in the passage suggest?","answer":"B","options":["Very few birds are ever harmed.","An enormous number of birds die this way each year.","Birds avoid the United States completely.","The danger has now disappeared."],"explanation":"对四亿到十亿、约十分之一的转述,说明死亡数量巨大。"},{"q":"Why are some kinds of birds hurt more than others?","answer":"C","options":["They fly only at night for fun.","They have stopped travelling altogether.","Their old travel routes still lead them through tall cities.","They are too heavy to turn quickly."],"explanation":"对 ''have not yet changed the old travelling routes… through cities full of high towers'' 的转述。"}]'::jsonb, '[{"word":"estimate","cn":"估计"},{"word":"migratory route","cn":"迁徙路线"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Staying Alive in the Wild', 'Spending time in nature is one of life''s great joys, but it can also be dangerous. Whether you are a first-time hiker or an old hand at camping, a few simple rules can save your life. First, if a wildfire breaks out, leave the area quickly but stay calm; panic will only slow you down. Second, when people get lost together, they often split up and each try to find the way home. This is a serious mistake. However tempting it feels, stay together as a group and wait for help to arrive. Third, wherever you go, take a first-aid kit with you, for it may one day save someone''s life — perhaps even your own. Carry enough water, too, since the body cannot last long without it. Above all, tell a friend where you are going before you set off, so that rescuers know where to look. No matter what goes wrong, a calm and hopeful mind remains the most powerful survival tool of all.', '应用文·野外求生提示', 166, '[{"q":"What should you do if a wildfire suddenly starts?","answer":"D","options":["Run in any direction as fast as you can.","Stay and watch the flames closely.","Hide near the burning trees.","Leave fast but keep yourself calm."],"explanation":"对 ''leave the area quickly but stay calm'' 的转述。"},{"q":"Why does the writer warn against splitting up when lost?","answer":"A","options":["Staying together makes rescue safer and easier.","It wastes the group''s food supply.","It frightens the wild animals away.","It makes the journey home faster."],"explanation":"对 ''stay together as a group and wait for help'' 的转述,劝阻各自走散。"},{"q":"What does the writer call the most powerful survival tool?","answer":"B","options":["A sharp knife and a map.","A calm and hopeful state of mind.","A loud voice for calling help.","A heavy bag of supplies."],"explanation":"对 ''a calm and hopeful mind remains the most powerful survival tool'' 的转述。"}]'::jsonb, '[{"word":"hiker","cn":"徒步者"},{"word":"first-aid kit","cn":"急救包"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Lesson of Robinson Crusoe', 'Daniel Defoe published Robinson Crusoe in 1719, and today it remains one of the most famous survival stories ever told. In the book, a man is shipwrecked and left completely alone on a desert island for many years. At first he has almost nothing, yet little by little he builds a new life. He makes simple tools, shapes cups out of clay, and even sews his own clothes. He digs a cave for shelter and learns to grow his own food. What truly saves him, however, is not his hands but his mind. Whatever troubles come, he stays calm and refuses to give in to fear. He is patient, clever and, above all, hopeful. Rather than thinking only about what he has lost, he counts what he still has. Countless readers have drawn courage from his story. His finest qualities — calmness, patience and a hopeful heart — are exactly the ones that can help any of us cope, no matter what kind of crisis we face.', '记叙·鲁滨逊的求生', 167, '[{"q":"How does Crusoe build a new life on the island?","answer":"C","options":["He slowly makes tools, shelter and food for himself.","He depends on other people living nearby.","He waits quietly for a passing ship.","He gives up and stops trying."],"explanation":"对 ''makes simple tools… digs a cave… learns to grow his own food'' 的概括转述。"},{"q":"According to the passage, what really saves Crusoe?","answer":"D","options":["The riches he carries from the ship.","The mild weather of the island.","A rescue team that soon arrives.","His calm, patient and hopeful mind."],"explanation":"对 ''What truly saves him… is not his hands but his mind'' 的转述。"},{"q":"Why do readers admire Crusoe''s story?","answer":"A","options":["His best qualities can help anyone face a crisis.","It is short and easy to read.","It describes a beautiful holiday island.","It teaches readers how to build a ship."],"explanation":"对末句 ''help any of us cope, no matter what kind of crisis'' 的转述。"}]'::jsonb, '[{"word":"shipwreck","cn":"船只失事"},{"word":"clay","cn":"黏土"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Mars: A Plan B for Humans?', 'Long ago, the greatest fear was that war could wipe out the human race in a single moment. Today, the biggest danger to life on Earth comes from our changing environment. Scientists are working hard to lower this risk, but they are also preparing for the worst. What, they ask, is our Plan B if the Earth one day becomes too damaged to live on? For many, the answer lies in space. Of all the planets, Mars looks the most promising, for it is fairly close to us and less hostile than the others. Space agencies are already planning to send people there within the next few decades. Yet the journey would be long and full of danger, and the first settlers might never return home. Staying alive on Mars would be a daily struggle. For now, human life on the Red Planet is still many years away. Until we can truly live elsewhere, the wisest plan of all is to take far better care of the only home we have.', '说明·火星作为B计划', 171, '[{"q":"What is the greatest danger to life on Earth today, according to the text?","answer":"B","options":["A sudden world war.","Our changing environment.","A shortage of spacecraft.","Too many wild animals."],"explanation":"对 ''the biggest danger to life on Earth comes from our changing environment'' 的转述。"},{"q":"Why is Mars seen as the most promising ''Plan B''?","answer":"C","options":["It already has cities for humans.","People can return from it in a single day.","It is fairly near and less harsh than other planets.","It is warmer than the Earth."],"explanation":"对 ''fairly close to us and less hostile than the others'' 的转述。"},{"q":"What does the writer suggest is the wisest plan for now?","answer":"D","options":["Sending settlers to Mars at once.","Forgetting about Earth completely.","Stopping all space research.","Taking far better care of our own planet."],"explanation":"对末句 ''take far better care of the only home we have'' 的转述。"}]'::jsonb, '[{"word":"hostile","cn":"恶劣的"},{"word":"settler","cn":"定居者"}]'::jsonb, 2, 'elective2', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'An Urban Fox', 'Late at night, a young fox slips into the streets of London to look for something to (1)____. Years ago, foxes lived only in the (2)____, but today many of them live right in the city. Far from their natural (3)____, such as larger animals that hunt them, these clever creatures feel safe. The fox soon learns that people leave plenty of food in the rubbish they (4)____ away. It can even open bins and other (5)____ to reach a meal. Some foxes have changed their habits and come out in (6)____, when there are fewer people about. The city is noisy and crowded, yet it gives the fox everything it needs to (7)____. Wherever new buildings go up, the fox quickly (8)____ to the change. It is no longer a (9)____ visitor from the woods but a true city animal. No matter how strange this seems, wild foxes have learned to (10)____ beside us.', 155, 2, '[{"q":"1","answer":"A","options":["eat","buy","read","wear"],"explanation":"look for something to eat 找吃的。"},{"q":"2","answer":"B","options":["classroom","countryside","kitchen","library"],"explanation":"foxes lived only in the countryside 乡间。"},{"q":"3","answer":"C","options":["teachers","friends","predators","buyers"],"explanation":"natural predators 天敌(后接 hunt them)。"},{"q":"4","answer":"D","options":["cook","grow","buy","throw"],"explanation":"rubbish they throw away 扔掉的垃圾。"},{"q":"5","answer":"A","options":["containers","songs","lessons","tickets"],"explanation":"open bins and other containers 容器。"},{"q":"6","answer":"B","options":["danger","daylight","winter","water"],"explanation":"come out in daylight 白天出来(fewer people)。"},{"q":"7","answer":"C","options":["forget","lose","survive","fail"],"explanation":"needs to survive 生存。"},{"q":"8","answer":"D","options":["refuses","returns","objects","adapts"],"explanation":"quickly adapts to the change 适应变化。"},{"q":"9","answer":"A","options":["rare","rich","late","loud"],"explanation":"no longer a rare visitor 罕见的访客。"},{"q":"10","answer":"B","options":["cry","live","sleep","hide"],"explanation":"learned to live beside us 与我们为邻而居。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'Clever City Racoons', 'Racoons that live in cities seem to be more (1)____ than their wild cousins. To find a meal, they must often (2)____ out tricky problems, such as how to open a rubbish bin. In the wild they would never (3)____ such containers, so they have had to learn fast. Scientists have (4)____ that urban racoons solve these puzzles more quickly than country ones. Like the fox, the racoon has changed its (5)____ to fit its new home. It comes out at night and searches the (6)____ that people throw away. There it can find all kinds of (7)____, from bread to meat. Life in the city is not always (8)____, because cars and dogs are real dangers. Yet, out of (9)____ from many natural predators, the racoon often does very well. No matter how hard the city makes life, these animals seem able to (10)____.', 145, 2, '[{"q":"1","answer":"C","options":["tired","afraid","intelligent","hungry"],"explanation":"more intelligent than their wild cousins 更聪明。"},{"q":"2","answer":"D","options":["run","sleep","sell","work"],"explanation":"work out tricky problems 解决难题。"},{"q":"3","answer":"A","options":["see","eat","buy","sing"],"explanation":"never see such containers in the wild 野外见不到。"},{"q":"4","answer":"B","options":["lost","found","sold","eaten"],"explanation":"Scientists have found that… 发现。"},{"q":"5","answer":"C","options":["prices","songs","habits","seats"],"explanation":"changed its habits 改变习性。"},{"q":"6","answer":"D","options":["music","water","sunlight","rubbish"],"explanation":"searches the rubbish people throw away 垃圾。"},{"q":"7","answer":"A","options":["food","noise","paper","glass"],"explanation":"all kinds of food, from bread to meat 食物。"},{"q":"8","answer":"B","options":["cheap","safe","clean","quiet"],"explanation":"not always safe, because cars and dogs are dangers 安全。"},{"q":"9","answer":"C","options":["order","date","reach","breath"],"explanation":"out of reach from predators 够不到、远离天敌。"},{"q":"10","answer":"D","options":["disappear","complain","forget","survive"],"explanation":"seem able to survive 生存。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'A Survival Kit', 'Spending time in the wild can be wonderful, but it can also be (1)____. Whether you are a first-time (2)____ or an experienced camper, you should always plan ahead. Wherever you go, take a first-aid (3)____ with you, because it could one day save a (4)____. If a wildfire suddenly breaks out, leave the area quickly but stay (5)____. Never (6)____ up the group when people get lost; instead, stay together and wait for help to (7)____. Always carry enough water, since you cannot live long without it. Tell someone where you are (8)____ before you set off, so they know where to look for you. However hard the journey becomes, do not give up (9)____. No matter what happens, a calm and (10)____ mind is the most important survival tool of all.', 133, 2, '[{"q":"1","answer":"A","options":["dangerous","cheap","sleepy","polite"],"explanation":"the wild can also be dangerous 危险。"},{"q":"2","answer":"B","options":["teacher","hiker","driver","singer"],"explanation":"a first-time hiker or camper 远足者。"},{"q":"3","answer":"C","options":["song","price","kit","seat"],"explanation":"a first-aid kit 急救包。"},{"q":"4","answer":"D","options":["game","price","song","life"],"explanation":"save a life 救命。"},{"q":"5","answer":"A","options":["calm","angry","proud","loud"],"explanation":"leave quickly but stay calm 冷静。"},{"q":"6","answer":"B","options":["wake","split","wash","pick"],"explanation":"never split up the group 分散。"},{"q":"7","answer":"C","options":["escape","begin","arrive","refuse"],"explanation":"wait for help to arrive 等救援到来。"},{"q":"8","answer":"D","options":["cooking","singing","buying","going"],"explanation":"where you are going 你要去哪儿。"},{"q":"9","answer":"A","options":["hope","money","water","food"],"explanation":"do not give up hope 别放弃希望。"},{"q":"10","answer":"B","options":["hungry","optimistic","sleepy","foreign"],"explanation":"a calm and optimistic mind 乐观的。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'When the Heat Comes', 'Every summer, a (1)____ heat wave hits parts of southern Europe. When the temperature (2)____ above forty degrees, the heat can be deadly. The government quickly (3)____ warnings and advises people to stay (4)____ during the hottest hours. Many families fill the swimming pools and (5)____ to cool down. Doctors warn that older people are in the most (6)____, so neighbours are asked to check on them. A heat wave is only one of the many (7)____ that the world now faces. Scientists believe such events will happen more (8)____ as the planet grows warmer. To (9)____ with the danger, cities are planting more trees and opening cool public rooms. However serious the problem becomes, people who stay calm and help one another will (10)____ it best.', 127, 2, '[{"q":"1","answer":"C","options":["gentle","short","fierce","quiet"],"explanation":"a fierce heat wave 酷烈的(deadly)。"},{"q":"2","answer":"D","options":["falls","sleeps","sells","rises"],"explanation":"the temperature rises above forty 升高。"},{"q":"3","answer":"A","options":["issues","eats","buys","loses"],"explanation":"issues warnings 发出警告。"},{"q":"4","answer":"B","options":["awake","indoors","abroad","asleep"],"explanation":"stay indoors during the hottest hours 室内。"},{"q":"5","answer":"C","options":["markets","libraries","beaches","factories"],"explanation":"pools and beaches to cool down 海滩。"},{"q":"6","answer":"D","options":["comfort","silence","hurry","danger"],"explanation":"in the most danger 最危险。"},{"q":"7","answer":"A","options":["crises","games","songs","prices"],"explanation":"many crises the world faces 危机。"},{"q":"8","answer":"B","options":["slowly","often","quietly","cheaply"],"explanation":"happen more often 更频繁。"},{"q":"9","answer":"C","options":["play","argue","cope","rest"],"explanation":"cope with the danger 应对。"},{"q":"10","answer":"D","options":["forget","waste","lose","handle"],"explanation":"will handle it best 处理得最好。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'Farming on Mars', 'It has been a week since the other astronauts left, and I am now (1)____ alone on Mars. A dust storm cut off our (2)____, and I was left behind. Luckily, the landing (3)____ protects me from the deadly radiation outside. My biggest worry at first was (4)____, but I have found an underground store of ice nearby. From the ice I can get the water I need and even (5)____ oxygen. Now my real problem is (6)____. There is only enough for about four (7)____, which is not long enough. Part of our mission was to grow plants in the Martian (8)____, so I have many kinds of seeds. I must work out how to (9)____ on Mars. No matter how hard it is, I refuse to give up. If I can solve this challenge, I will (10)____ until a rescue ship finally arrives.', 145, 2, '[{"q":"1","answer":"A","options":["left","sent","paid","sold"],"explanation":"now left alone on Mars 被独自留下。"},{"q":"2","answer":"B","options":["breakfast","communication","holiday","music"],"explanation":"cut off our communication 切断通讯。"},{"q":"3","answer":"C","options":["garden","library","capsule","market"],"explanation":"the landing capsule protects me 着陆舱。"},{"q":"4","answer":"D","options":["money","homework","music","water"],"explanation":"biggest worry was water(后接 ice/water)。"},{"q":"5","answer":"A","options":["produce","sell","forget","lose"],"explanation":"get water and even produce oxygen 制造氧气。"},{"q":"6","answer":"B","options":["sleep","food","noise","rain"],"explanation":"my real problem is food(后接 seeds/farm)。"},{"q":"7","answer":"C","options":["seconds","metres","months","coins"],"explanation":"enough for about four months 四个月。"},{"q":"8","answer":"D","options":["snow","glass","cloud","soil"],"explanation":"grow plants in the Martian soil 土壤。"},{"q":"9","answer":"A","options":["farm","sleep","sing","drive"],"explanation":"how to farm on Mars 种地。"},{"q":"10","answer":"B","options":["disappear","survive","relax","quit"],"explanation":"I will survive until rescue arrives 活下去。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U6', 'Lizards That Changed', 'The green lizards of Florida once lived happily on the lower (1)____ and trunks of the trees. Then a tougher kind, the brown lizards, was (2)____ from Cuba. Suddenly there was not enough (3)____ for everyone, and the green lizards came under great (4)____. To stay away from their new (5)____, they moved higher up the trees. Up there, the branches were smoother and much harder to (6)____. Over a fairly short time of about fifteen (7)____, the green lizards began to change. They grew bigger pads on their (8)____ and stickier skin to help them hold on. In this way they could stay high and (9)____ from the brown lizards below. The story shows that, no matter how tough life becomes, living things can (10)____ to survive.', 128, 2, '[{"q":"1","answer":"C","options":["windows","streets","branches","rivers"],"explanation":"lower branches and trunks 枝条。"},{"q":"2","answer":"D","options":["forgotten","painted","sold","introduced"],"explanation":"was introduced from Cuba 被引入。"},{"q":"3","answer":"A","options":["food","music","paper","light"],"explanation":"not enough food for everyone 食物。"},{"q":"4","answer":"B","options":["comfort","pressure","silence","colour"],"explanation":"came under great pressure 压力。"},{"q":"5","answer":"C","options":["teachers","buyers","neighbours","singers"],"explanation":"away from their new neighbours 邻居(指棕蜥蜴)。"},{"q":"6","answer":"D","options":["buy","sell","read","grip"],"explanation":"smoother and harder to grip 抓握。"},{"q":"7","answer":"A","options":["years","seconds","metres","coins"],"explanation":"about fifteen years 年。"},{"q":"8","answer":"B","options":["books","toes","cars","songs"],"explanation":"bigger pads on their toes 脚趾。"},{"q":"9","answer":"C","options":["late","rich","safe","loud"],"explanation":"stay high and safe from the brown lizards 安全。"},{"q":"10","answer":"D","options":["refuse","forget","complain","adapt"],"explanation":"living things can adapt to survive 适应。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 Planning a Survival Story', '外研社版选择性必修第二册 U6 · dialogue', 3, 'Mia: Let''s write a survival story together. Where should we set it?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 Animals in Our Cities', '外研社版选择性必修第二册 U6 · passage', 2, 'More and more wild animals are moving into our cities.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 A Snake Bite in the Wild', '外研社版选择性必修第二册 U6 · dialogue', 3, 'Anna: Help! A snake just bit Tom''s leg while we were hiking.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 Birds and Glass', '外研社版选择性必修第二册 U6 · passage', 2, 'Many birds cannot tell the difference between the open sky and clear glass.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·对话 Talking about Robinson Crusoe', '外研社版选择性必修第二册 U6 · dialogue', 3, 'Sam: I''ve just finished Robinson Crusoe. What a survival story!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U6 听力·短文 A Tip for a Crisis', '外研社版选择性必修第二册 U6 · passage', 2, 'Here is one simple tip for facing any crisis.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Survival Story(写一篇求生故事)', 'Survival', '想象你被困在一个危险的地方(如南极、太空、丛林),必须设法活下来。用英语写一篇约 90 词的求生故事,内容包括:① 你在哪里、面对什么危险;② 你已经做了什么来活下来;③ 你接下来打算怎么做;④ 你的心情。要求至少用上一个 -ever 或 no matter 引导的让步状语从句。', 'Imagine you are trapped in a dangerous place (for example, Antarctica, space or the jungle) and must survive. Write a short survival story of about 90 words. Include: 1) where you are and what dangers you face; 2) what you have already done to stay alive; 3) what you plan to do next; 4) how you feel. Use at least one adverbial clause with -ever or no matter.', '["交代地点与危险(I am trapped in … / The biggest danger is …)","已做的求生行动(So far, I have … to stay alive)","下一步打算(Next, I will … / My plan is to …)","心情 + 用上 -ever / no matter 从句(However hard it is, I will not give up. / No matter what happens, …)"]'::jsonb, 70, 100, 'I am trapped alone on Mars after a dust storm cut me off from the others. The biggest dangers are the deadly radiation outside and my shrinking supply of food. So far, I have stayed inside the landing capsule and found an underground store of ice, which gives me water and oxygen. Next, I will try to grow plants in the Martian soil with the seeds I carry. However hard this is, I refuse to give up. No matter what happens, I will keep calm and hopeful until rescue comes.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I am trapped alone on Mars after a dust storm cut me off from the others.","So far, I have stayed inside the landing capsule and found an underground store of ice.","However hard this is, I refuse to give up.","No matter what happens, I will keep calm and hopeful until rescue comes."]'::jsonb, '[{"wrong":"However it is hard, I will not give up.","correct":"However hard it is, I will not give up.","note":"however 后紧跟形容词/副词:however + adj. + 主语 + 谓语。"},{"wrong":"No matter what happen, I keep calm.","correct":"No matter what happens, I keep calm.","note":"what 作主语时谓语用第三人称单数 happens。"},{"wrong":"Whatever the danger is, but I keep trying.","correct":"Whatever the danger is, I keep trying.","note":"让步状语从句后主句不再用 but;-ever 从句本身已含让步义。"}]'::jsonb, '【求生故事结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U6', '{"title":"-ever 与 no matter 引导的让步状语从句速查","intro":"whatever/whoever/whichever/wherever/whenever/however 引导让步状语从句,意为“无论……”,都可换成 no matter + what/who/which/where/when/how。判断口诀:看从句缺什么成分,就用对应的 -ever 词;这些词本身充当主语/宾语/限定词/状语,所以 though/although 不能替换。","table":{"headers":["-ever 词","= no matter …","在从句中的角色 / 例句"],"rows":[["whatever","no matter what","指物,作主语/宾语/限定词:Whatever happens, stay calm."],["whoever","no matter who","指人,作主语/宾语:Whoever finds the ice will help us."],["whichever","no matter which","从一组中择一,作限定词:Whichever path you take, be careful."],["wherever","no matter where","指地点,作状语:Wherever they go, animals find cities in their way."],["whenever","no matter when","指时间,作状语:Whenever a fire breaks out, leave calmly."],["however + adj./adv.","no matter how + adj./adv.","表程度:However hard it is, don''t give up."]]},"specialRules":[{"rule":"however 在这里 = no matter how,后面必须紧跟形容词或副词,再接“主语+谓语”","mark":"However fast the birds fly, some still crash.(However + adv. + 主谓)"},{"rule":"别把让步的 however 和表示“但是”的 however 混淆","mark":"It is dangerous; however, we go on.(=but,作连接副词)"},{"rule":"whatever/whoever 既能引导让步状语,也能引导名词性从句作主语/宾语","mark":"让步:Whatever happens, … ｜ 名词从句:Take whatever you need."},{"rule":"though/although 引导让步从句时后接“完整主谓”,不能充当从句的主语/宾语/限定词","mark":"Although he committed crimes √ / Although happens ×"}],"why":["-ever 词把“让步”和“在从句里充当某个成分(主语/宾语/状语/限定词)”合二为一,所以它后面跟的是一个缺成分的从句;though/although 只表让步、不充当成分,因此两者不能互换。"],"gaokaoPoints":["语法填空高频:根据从句缺的成分及指人/指物/指地点/指时间,选 whatever/whoever/wherever/whenever/however。","however + adj./adv. = no matter how 是易错点;however 后绝不能直接接名词。","-ever 词与 no matter + 疑问词 的互换改写常考。"],"examVsReal":[{"exam":"No matter what happens, we will go on.（考试/书面)","real":"Whatever happens, we''ll go on.","note":"口语里 -ever 单词形式更简洁,意思完全相同"},{"exam":"However hard it is, she keeps trying.（考试)","real":"No matter how hard it is, she keeps trying.","note":"两种写法可互换;口语两者都常见"}]}'::jsonb, 'fltrp');
